package com.carrental.dao.jdbc;

import com.carrental.exception.BookingNotFoundException;
import com.carrental.exception.CarNotAvailableException;
import com.carrental.model.BookingReceipt;
import com.carrental.util.Database;
import com.carrental.service.BookingRules;
import java.math.BigDecimal;
import java.sql.*;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;
import java.util.function.Function;

public class JdbcBookingRepository {
    public BookingReceipt create(long customerId,long carId,LocalDate start,LocalDate end,Function<BigDecimal,BigDecimal> priceCalculator) throws SQLException {
        String lock="SELECT status,daily_rate FROM cars WHERE id=? FOR UPDATE";
        String overlap="SELECT COUNT(*) FROM bookings b LEFT JOIN rentals r ON r.booking_id=b.id WHERE b.car_id=? AND b.status IN ('CONFIRMED','ACTIVE') AND b.pickup_date < ? AND (b.return_date > ? OR (b.status='ACTIVE' AND r.actual_return_at IS NULL))";
        String insert="INSERT INTO bookings(booking_reference,customer_id,car_id,pickup_date,return_date,daily_rate,rental_days,base_amount,status) VALUES(?,?,?,?,?,?,?,?, 'CONFIRMED')";
        try(Connection c=Database.getConnection()){c.setAutoCommit(false);try {
            String status;BigDecimal rate;try(PreparedStatement p=c.prepareStatement(lock)){p.setLong(1,carId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new CarNotAvailableException("That car no longer exists.");status=r.getString(1);rate=r.getBigDecimal(2);}}
            long conflicts;try(PreparedStatement p=c.prepareStatement(overlap)){p.setLong(1,carId);p.setDate(2,java.sql.Date.valueOf(end));p.setDate(3,java.sql.Date.valueOf(start));try(ResultSet r=p.executeQuery()){r.next();conflicts=r.getLong(1);}}
            if(!BookingRules.canBook(status,conflicts>0))throw new CarNotAvailableException(conflicts>0?"That car already has a booking for some of those dates.":"This car is not currently available for booking.");
            int days=Math.toIntExact(ChronoUnit.DAYS.between(start,end));BigDecimal base=priceCalculator.apply(rate);String ref="CR-"+Year.now().getValue()+"-"+UUID.randomUUID().toString().replace("-","").substring(0,12).toUpperCase(Locale.ROOT);
            long id;try(PreparedStatement p=c.prepareStatement(insert,Statement.RETURN_GENERATED_KEYS)){p.setString(1,ref);p.setLong(2,customerId);p.setLong(3,carId);p.setDate(4,java.sql.Date.valueOf(start));p.setDate(5,java.sql.Date.valueOf(end));p.setBigDecimal(6,rate);p.setInt(7,days);p.setBigDecimal(8,base);p.executeUpdate();try(ResultSet keys=p.getGeneratedKeys()){if(!keys.next())throw new SQLException("Booking reference could not be recorded");id=keys.getLong(1);}}
            try(PreparedStatement p=c.prepareStatement("INSERT INTO payments(booking_id,amount,payment_status,method) VALUES(?,?,'PENDING','SIMULATED')")){p.setLong(1,id);p.setBigDecimal(2,base);p.executeUpdate();}
            c.commit();return new BookingReceipt(id,ref,days,rate,base);
        } catch(RuntimeException|SQLException ex){try{c.rollback();}catch(SQLException rollback){ex.addSuppressed(rollback);}throw ex;}}
    }
    public List<Map<String,Object>> forCustomer(long customerId)throws SQLException{return query("WHERE b.customer_id=? ORDER BY b.pickup_date DESC",customerId);}
    public List<Map<String,Object>> all(String term,String status)throws SQLException {
        StringBuilder q=new StringBuilder("WHERE 1=1");List<Object>a=new ArrayList<>();if(term!=null&&!term.isBlank()){q.append(" AND (b.booking_reference LIKE ? OR CAST(b.id AS CHAR)=?)");a.add("%"+term.trim()+"%");a.add(term.trim());}if(status!=null&&!status.isBlank()){q.append(" AND b.status=?");a.add(status);}q.append(" ORDER BY b.created_at DESC");return queryMany(q.toString(),a);
    }
    public Map<String,Object> customerBooking(long customerId,long bookingId)throws SQLException {List<Map<String,Object>> rows=query("WHERE b.customer_id=? AND b.id=?",customerId,bookingId);return rows.isEmpty()?null:rows.get(0);}
    public Map<String,Object> booking(long bookingId)throws SQLException {List<Map<String,Object>> rows=query("WHERE b.id=?",bookingId);return rows.isEmpty()?null:rows.get(0);}
    public Map<String,Object> invoice(long customerId,long bookingId)throws SQLException {return customerBooking(customerId,bookingId);}
    public boolean cancelCustomer(long customerId,long bookingId)throws SQLException {return cancel(bookingId,customerId);}
    public boolean cancelAdmin(long bookingId)throws SQLException {return cancel(bookingId,null);}
    private boolean cancel(long bookingId,Long customerId)throws SQLException {try(Connection c=Database.getConnection()){c.setAutoCommit(false);try{String sql="SELECT status,pickup_date FROM bookings WHERE id=?"+(customerId==null?"":" AND customer_id=?")+" FOR UPDATE";String status;LocalDate pickup;try(PreparedStatement p=c.prepareStatement(sql)){p.setLong(1,bookingId);if(customerId!=null)p.setLong(2,customerId);try(ResultSet r=p.executeQuery()){if(!r.next()){c.commit();return false;}status=r.getString(1);pickup=r.getDate(2).toLocalDate();}}if(!BookingRules.canCancel(status,pickup,LocalDate.now())){c.commit();return false;}try(PreparedStatement p=c.prepareStatement("UPDATE bookings SET status='CANCELLED' WHERE id=? AND status='CONFIRMED' AND pickup_date>CURRENT_DATE")){p.setLong(1,bookingId);boolean changed=p.executeUpdate()==1;c.commit();return changed;}}catch(RuntimeException|SQLException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}
    public void pickup(long bookingId)throws SQLException {try(Connection c=Database.getConnection()){c.setAutoCommit(false);try{String status;try(PreparedStatement p=c.prepareStatement("SELECT status FROM bookings WHERE id=? FOR UPDATE")){p.setLong(1,bookingId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new BookingNotFoundException("Booking not found.");status=r.getString(1);}}if(!"CONFIRMED".equals(status))throw new IllegalStateException("Only a confirmed booking can be picked up.");try(PreparedStatement p=c.prepareStatement("INSERT INTO rentals(booking_id,pickup_at,late_fee_per_day) VALUES(?,NOW(),25.00)")){p.setLong(1,bookingId);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("UPDATE bookings SET status='ACTIVE' WHERE id=?")){p.setLong(1,bookingId);p.executeUpdate();}c.commit();}catch(RuntimeException|SQLException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}
    public void returnRental(long bookingId)throws SQLException {try(Connection c=Database.getConnection()){c.setAutoCommit(false);try{LocalDate planned;long carId;String status;try(PreparedStatement p=c.prepareStatement("SELECT b.return_date,b.car_id,b.status FROM bookings b WHERE b.id=? FOR UPDATE")){p.setLong(1,bookingId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new BookingNotFoundException("Booking not found.");planned=r.getDate(1).toLocalDate();carId=r.getLong(2);status=r.getString(3);}}if(!"ACTIVE".equals(status))throw new IllegalStateException("Only an active rental can be returned.");LocalDate today=LocalDate.now();int lateDays=Math.max(0,Math.toIntExact(ChronoUnit.DAYS.between(planned,today)));BigDecimal perDay=new BigDecimal("25.00"),fee=perDay.multiply(BigDecimal.valueOf(lateDays));
        try(PreparedStatement p=c.prepareStatement("UPDATE rentals SET actual_return_at=NOW(),late_days=?,late_fee=?,final_charge=(SELECT base_amount FROM bookings WHERE id=?)+? WHERE booking_id=? AND actual_return_at IS NULL")){p.setInt(1,lateDays);p.setBigDecimal(2,fee);p.setLong(3,bookingId);p.setBigDecimal(4,fee);p.setLong(5,bookingId);if(p.executeUpdate()!=1)throw new IllegalStateException("Rental return was already recorded.");}
        try(PreparedStatement p=c.prepareStatement("UPDATE bookings SET status='COMPLETED' WHERE id=?")){p.setLong(1,bookingId);p.executeUpdate();}
        try(PreparedStatement p=c.prepareStatement("UPDATE payments SET amount=(SELECT final_charge FROM rentals WHERE booking_id=?),payment_status='SIMULATED_PAID',paid_at=NOW() WHERE booking_id=?")){p.setLong(1,bookingId);p.setLong(2,bookingId);p.executeUpdate();}
        try(PreparedStatement p=c.prepareStatement("UPDATE cars SET status='AVAILABLE' WHERE id=? AND status='UNAVAILABLE'")){p.setLong(1,carId);p.executeUpdate();}c.commit();
    }catch(RuntimeException|SQLException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}
    private List<Map<String,Object>> query(String where,Object... args)throws SQLException{return queryMany(where,Arrays.asList(args));}
    private List<Map<String,Object>> queryMany(String where,List<Object> args)throws SQLException {
        String sql="SELECT b.id,b.booking_reference,b.customer_id,b.car_id,b.pickup_date,b.return_date,b.daily_rate,b.rental_days,b.base_amount,b.status,b.created_at,c.full_name,c.phone,u.email,ca.brand,ca.model,ca.registration_number,COALESCE(r.late_days,0) late_days,COALESCE(r.late_fee,0) late_fee,COALESCE(r.final_charge,b.base_amount) final_charge,r.pickup_at,r.actual_return_at FROM bookings b JOIN customers c ON c.id=b.customer_id JOIN users u ON u.id=c.user_id JOIN cars ca ON ca.id=b.car_id LEFT JOIN rentals r ON r.booking_id=b.id "+where;
        try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(sql)){for(int i=0;i<args.size();i++)p.setObject(i+1,args.get(i));try(ResultSet r=p.executeQuery()){List<Map<String,Object>> out=new ArrayList<>();while(r.next()){Map<String,Object>m=new LinkedHashMap<>();m.put("id",r.getLong("id"));m.put("reference",r.getString("booking_reference"));m.put("customerId",r.getLong("customer_id"));m.put("carId",r.getLong("car_id"));m.put("pickupDate",r.getDate("pickup_date").toLocalDate().toString());m.put("returnDate",r.getDate("return_date").toLocalDate().toString());m.put("dailyRate",r.getBigDecimal("daily_rate"));m.put("rentalDays",r.getInt("rental_days"));m.put("baseAmount",r.getBigDecimal("base_amount"));m.put("status",r.getString("status"));m.put("customerName",r.getString("full_name"));m.put("phone",r.getString("phone"));m.put("email",r.getString("email"));m.put("brand",r.getString("brand"));m.put("model",r.getString("model"));m.put("registrationNumber",r.getString("registration_number"));m.put("lateDays",r.getInt("late_days"));m.put("lateFee",r.getBigDecimal("late_fee"));m.put("finalCharge",r.getBigDecimal("final_charge"));Timestamp pickup=r.getTimestamp("pickup_at"),returned=r.getTimestamp("actual_return_at");m.put("pickupAt",pickup==null?null:pickup.toLocalDateTime().toString());m.put("actualReturnAt",returned==null?null:returned.toLocalDateTime().toString());out.add(m);}return out;}}
    }
}
